from pathlib import Path
import json,hashlib,collections,datetime
D=Path(__file__).parent;B=D.parent/'mention-canonical-normalization-v1/prepared-v1';rows=[json.loads(v) for v in (B/'train.jsonl').read_text().splitlines()];names=json.loads((B/'public-names.json').read_text());raw=json.loads((D/'query-v1-collected/actual/results.json').read_text());q={v['quote']:v for v in raw};assert len(rows)==2353 and len(raw)==len(q)==1284
stats=collections.Counter();per=[];ranks=collections.Counter();unique_atoms={};nothpo=collections.Counter()
for row in rows:
 r=q[row['quote']];ids=[x['identifier'] for x in r['candidates']];assert len(ids)==len(set(ids))==8
 status=row['target_status'];stats['rows']+=1;stats['rows_'+status]+=1
 gold=[names[x] for x in json.loads(row['answer'])] if status=='HPO' else [];assert len(gold)==len(set(gold));hit=[x for x in gold if x in ids];missing=sorted(set(gold)-set(ids));positions=[ids.index(x)+1 for x in hit]
 if status=='HPO':
  stats['gold_atoms']+=len(gold);stats['gold_atoms_cover1']+=sum(x in ids[:1] for x in gold);stats['gold_atoms_cover8']+=len(hit);stats['HPO_all_covered8']+=int(not missing);stats['HPO_some_covered8']+=int(bool(hit));stats['HPO_none_covered8_OTHER']+=int(not hit);stats['HPO_partial_covered8']+=int(bool(hit) and bool(missing));stats['HPO_all_covered1']+=int(set(gold)<=set(ids[:1]));stats['HPO_first_correct']+=int(ids[0] in gold);stats['HPO_compound_rows']+=int(len(gold)>1);stats['HPO_multi_positive_options']+=int(len(hit)>1);stats['HPO_all_covered8_top1_wrong_competitive']+=int(not missing and ids[0] not in gold);stats['HPO_any_covered8_top1_wrong_competitive']+=int(bool(hit) and ids[0] not in gold)
  for x in gold:ranks[str(ids.index(x)+1) if x in ids else 'missing']+=1;unique_atoms[(row['quote'],x)]={'cover1':x in ids[:1],'cover8':x in ids}
 else:nothpo[status]+=1
 per.append({'row_id':row['row_id'],'pmc_id':row['pmc_id'],'quote':row['quote'],'target_status':status,'gold_ids':gold,'candidate_ids':ids,'correct_option_positions':positions,'missing_gold_ids':missing,'retrieval_status':r['status']})
assert stats['rows_HPO']==2222 and stats['rows_NO']==87 and stats['rows_NIL']==44
out={'status':'TRAIN32_COMPLETE_PUBLIC_TOP8_CENSUS_NO_MODEL_QUALITY','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'counts':dict(stats),'gold_atom_cover1':stats['gold_atoms_cover1']/stats['gold_atoms'],'gold_atom_cover8':stats['gold_atoms_cover8']/stats['gold_atoms'],'rank_histogram':dict(ranks),'distinct_quote_gold_atom_counts':{'total':len(unique_atoms),'cover1':sum(x['cover1'] for x in unique_atoms.values()),'cover8':sum(x['cover8'] for x in unique_atoms.values())},'row_policy':'all2353 frozen rows; no gold inserted into retrieved candidates; NO/NIL supervised state separate; missing HPO=OTHER, partial compound retains missing atom evidence','quality_claim':False,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'inputs':{str(p):{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [B/'train.jsonl',B/'public-names.json',D/'query-v1-collected/actual/results.json',D/'query-v1-collected/actual/complete.json']}}
(D/'census.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');(D/'training-row-candidates.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in per));print(json.dumps(out,ensure_ascii=False))
